core_reasoning_1:
\noindent\textbf{Claim.} In the $n_{12}=1$ sector on $\mathbb{R}\times T^2\times S^1$, the non-flat Abelian background
\[
F_{12}^{(i)}=\frac{2\pi}{L_1L_2}H^{(i)},\qquad H^{(i)}=\operatorname{diag}(0,\ldots,1,\ldots,0)-\frac{1}{N}{\bf 1}_N,
\]
has classical energy
\[
E^{\rm cl}_{\rm non\text{-}flat}=\frac{L_3}{2L_1L_2}\left(\frac{2\pi}{g}\right)^2\left(1-\frac{1}{N}\right).
\]
For the symmetric torus $L_1=L_2=L_T$, comparison with the flat realization gives
\[
\frac{\Delta E^{\rm cl}_{\rm non\text{-}flat}}{\Delta E^{1\text{-}{\rm loop}}_{\rm flat}}\propto \frac{L_3^4}{N\lambda L_T^4},\qquad \lambda:=g^2N.
\]
Consequently, the non-flat realization is energetically preferred when $L_T^4\gg L_3^4/(N\lambda)$, while the flat realization is preferred when $L_T^4\ll L_3^4/(N\lambda)$.

\noindent\textbf{Premises.}
\[
\begin{aligned}
\mathrm{(P1)}&\quad N\geq 2,\quad L_1,L_2,L_3,g,\lambda>0,\quad \lambda:=g^2N.\\
\mathrm{(P2)}&\quad F_{12}^{(i)}=\frac{2\pi}{L_1L_2}H^{(i)},\quad H^{(i)}=\operatorname{diag}(0,\ldots,1,\ldots,0)-\frac{1}{N}{\bf 1}_N.\\
\mathrm{(P3)}&\quad E^{\rm cl}_{\rm non\text{-}flat}:=\frac{1}{2g^2}\int_{T^2\times S^1}\operatorname{tr}\left[(F_{12}^{(i)})^2\right].\\
\mathrm{(P4)}&\quad \operatorname{Vol}(T^2\times S^1)=L_1L_2L_3.\\
\mathrm{(P5)}&\quad \Delta E^{\rm cl}_{\rm non\text{-}flat}\propto \frac{N}{\lambda}\frac{L_3^2}{L_1L_2}\frac{1}{L_3},\quad
\Delta E^{1\text{-}{\rm loop}}_{\rm flat}\propto N^2\frac{L_1L_2}{L_3^2}\frac{1}{L_3}.\\
\mathrm{(P6)}&\quad L_1=L_2=L_T\quad \text{in the symmetric torus comparison.}\\
\mathrm{(P7)}&\quad \text{For positive energies, }\Delta E_A\ll \Delta E_B\text{ means realization }A\text{ is energetically preferred over }B.
\end{aligned}
\]

\noindent\textbf{Derivation.}
\begin{align}
H^{(i)}_{ii} &= 1-\frac{1}{N}, \qquad H^{(i)}_{aa}=-\frac{1}{N}\quad (a\neq i) && \text{by (P2)},\\
\operatorname{tr}\left[(H^{(i)})^2\right]
&=\left(1-\frac{1}{N}\right)^2+(N-1)\left(\frac{1}{N}\right)^2 && \text{trace of a diagonal matrix},\\
&=1-\frac{2}{N}+\frac{1}{N^2}+\frac{N-1}{N^2} && \text{expand},\\
&=1-\frac{2}{N}+\frac{N}{N^2} && \text{combine fractions},\\
&=1-\frac{1}{N}. && \text{simplify}
\end{align}
\begin{align}
\operatorname{tr}\left[(F_{12}^{(i)})^2\right]
&=\left(\frac{2\pi}{L_1L_2}\right)^2\operatorname{tr}\left[(H^{(i)})^2\right] && \text{by (P2)},\\
&=\left(\frac{2\pi}{L_1L_2}\right)^2\left(1-\frac{1}{N}\right) && \text{previous result}.
\end{align}
\begin{align}
E^{\rm cl}_{\rm non\text{-}flat}
&=\frac{1}{2g^2}\int_{T^2\times S^1}\operatorname{tr}\left[(F_{12}^{(i)})^2\right] && \text{by (P3)},\\
&=\frac{1}{2g^2}(L_1L_2L_3)\left(\frac{2\pi}{L_1L_2}\right)^2\left(1-\frac{1}{N}\right) && \text{by (P4)},\\
&=\frac{L_3}{2L_1L_2}\left(\frac{2\pi}{g}\right)^2\left(1-\frac{1}{N}\right). && \text{cancel }L_1L_2
\end{align}
\begin{align}
\frac{\Delta E^{\rm cl}_{\rm non\text{-}flat}}{\Delta E^{1\text{-}{\rm loop}}_{\rm flat}}
&\propto
\frac{\frac{N}{\lambda}\frac{L_3^2}{L_1L_2}\frac{1}{L_3}}{N^2\frac{L_1L_2}{L_3^2}\frac{1}{L_3}} && \text{by (P5)},\\
&=\frac{N}{\lambda}\frac{L_3}{L_1L_2}\cdot \frac{L_3^3}{N^2L_1L_2} && \text{invert denominator},\\
&=\frac{L_3^4}{N\lambda (L_1L_2)^2} && \text{collect factors},\\
&=\frac{L_3^4}{N\lambda L_T^4} && \text{by (P6)}.
\end{align}
\begin{align}
\Delta E^{\rm cl}_{\rm non\text{-}flat}\ll \Delta E^{1\text{-}{\rm loop}}_{\rm flat}
&\Longleftrightarrow \frac{L_3^4}{N\lambda L_T^4}\ll 1 && \text{positive energies and previous ratio},\\
&\Longleftrightarrow L_T^4\gg \frac{L_3^4}{N\lambda} && \text{multiply by }N\lambda L_T^4,\\
&\Longrightarrow \text{non-flat realization is energetically preferred} && \text{by (P7)},\\
\Delta E^{1\text{-}{\rm loop}}_{\rm flat}\ll \Delta E^{\rm cl}_{\rm non\text{-}flat}
&\Longleftrightarrow L_T^4\ll \frac{L_3^4}{N\lambda} && \text{opposite inequality},\\
&\Longrightarrow \text{flat realization is energetically preferred}. && \text{by (P7)}
\end{align}

\noindent\textbf{Final Result.}
\[
\boxed{E^{\rm cl}_{\rm non\text{-}flat}=\frac{L_3}{2L_1L_2}\left(\frac{2\pi}{g}\right)^2\left(1-\frac{1}{N}\right),\quad
\frac{\Delta E^{\rm cl}_{\rm non\text{-}flat}}{\Delta E^{1\text{-}{\rm loop}}_{\rm flat}}\propto \frac{L_3^4}{N\lambda L_T^4},\quad
\begin{array}{l}
L_T^4\gg L_3^4/(N\lambda):\ \text{non-flat preferred},\\
L_T^4\ll L_3^4/(N\lambda):\ \text{flat preferred}
\end{array}}
\]
\hfill$\blacksquare$

core_reasoning_3:
\noindent\textbf{Claim.} In the quantum-mechanical reduction with $n_{12}=1$ and $N\geq 3$, the topological coupling shifts the integer momenta by $j/N$, giving the free Hamiltonian spectrum
\[
\frac{E_{\{m_n\}}}{C}=\sum_{j=1}^{N-2}\left[\left(m_j-\frac{j}{N}\right)-\left(m_{j+1}-\frac{j+1}{N}\right)\right]^2+\left(m_1-\frac{1}{N}\right)^2+\left(m_{N-1}-\frac{N-1}{N}\right)^2,
\]
where $m_j\in\mathbb{Z}$ and $C=L_3(2\pi/g)^2/(2L_1L_2)$. The minimum is $E_{\rm gs}=C(N-1)/N$, and the $N$ minimizers are precisely
\[
|0,\ldots,0\rangle,\quad |0,\ldots,0,1\rangle,
\quad |0,\ldots,0,1,1\rangle,
\quad \ldots,
\quad |1,\ldots,1\rangle.
\]

\noindent\textbf{Premises.}
\[
\begin{aligned}
\mathrm{(P1)}&\quad N\geq 3,
\quad m_j\in\mathbb{Z},
\quad C:=\frac{L_3}{2L_1L_2}\left(\frac{2\pi}{g}\right)^2>0.\\
\mathrm{(P2)}&\quad H/C=\sum_{i,j=1}^{N-1}A_{ij}\left(p_i-\frac{i}{N}\right)\left(p_j-\frac{j}{N}\right),\quad n_{12}=1.\\
\mathrm{(P3)}&\quad A_{ij}=2\delta_{ij}-\delta_{i,j+1}-\delta_{i,j-1}.\\
\mathrm{(P4)}&\quad p_j|m_1,\ldots,m_{N-1}\rangle=m_j|m_1,\ldots,m_{N-1}\rangle.\\
\mathrm{(P5)}&\quad \sum_{i,j=1}^{N-1}A_{ij}h_ih_j=\sum_{j=1}^{N-2}(h_j-h_{j+1})^2+h_1^2+h_{N-1}^2.\\
\mathrm{(P6)}&\quad \text{If }u,v\in\mathbb{Z},\ u-v\geq 3,\text{ then }(u+a)^2+(v+a)^2>(u-1+a)^2+(v+1+a)^2\text{ for any }a\in\mathbb{R}.
\end{aligned}
\]

\noindent\textbf{Derivation.}
\begin{align}
h_j&:=m_j-\frac{j}{N} && \text{definition},\\
\frac{E_{\{m_n\}}}{C}
&=\sum_{i,j=1}^{N-1}A_{ij}h_ih_j && \text{by (P2) and (P4)},\\
&=\sum_{j=1}^{N-2}(h_j-h_{j+1})^2+h_1^2+h_{N-1}^2 && \text{by (P5)},\\
&=\sum_{j=1}^{N-2}\left[\left(m_j-\frac{j}{N}\right)-\left(m_{j+1}-\frac{j+1}{N}\right)\right]^2
+\left(m_1-\frac{1}{N}\right)^2+\left(m_{N-1}-\frac{N-1}{N}\right)^2. && \text{substitute }h_j
\end{align}
Set $m_0:=0$, $m_N:=1$, $h_0:=0$, and $h_N:=0$. Then
\begin{align}
\frac{E_{\{m_n\}}}{C}
&=\sum_{j=0}^{N-1}(h_j-h_{j+1})^2 && \text{include the endpoint terms},\\
d_j&:=h_j-h_{j+1}=m_j-m_{j+1}+\frac{1}{N}=:z_j+\frac{1}{N} && \text{definition},\\
z_j&:=m_j-m_{j+1}\in\mathbb{Z} && \text{integer differences},\\
\sum_{j=0}^{N-1}z_j&=m_0-m_N=-1 && \text{telescoping sum}.
\end{align}
Therefore minimizing $E/C$ is equivalent to minimizing
\begin{align}
\sum_{j=0}^{N-1}\left(z_j+\frac{1}{N}\right)^2
\quad \text{subject to}\quad z_j\in\mathbb{Z},\quad \sum_{j=0}^{N-1}z_j=-1. && \text{from the previous lines}
\end{align}
If some pair satisfies $z_a-z_b\geq 3$, then replacing $(z_a,z_b)$ by $(z_a-1,z_b+1)$ preserves the integer sum and lowers the objective by (P6). Repeating this smoothing step gives a minimizer with all entries differing by at most $1$. Since the integer sum is $-1$ over $N$ entries, the only such configuration is
\begin{align}
\{z_0,\ldots,z_{N-1}\}&=\{-1,0,\ldots,0\} && \text{one }-1\text{ and }N-1\text{ zeros}.
\end{align}
Thus
\begin{align}
\frac{E_{\rm gs}}{C}
&=\left(-1+\frac{1}{N}\right)^2+(N-1)\left(0+\frac{1}{N}\right)^2 && \text{substitute the minimizing }z_j,\\
&=\left(\frac{N-1}{N}\right)^2+(N-1)\left(\frac{1}{N}\right)^2 && \text{square the negative term},\\
&=\frac{(N-1)^2+N-1}{N^2} && \text{common denominator},\\
&=\frac{N-1}{N}. && \text{simplify}
\end{align}
If the unique entry $z_s=-1$ is placed at $s=N-1-r$ for $r=0,1,\ldots,N-1$, solving $z_j=m_j-m_{j+1}$ with $m_0=0$ gives
\begin{align}
m_j^{(r)}&=\begin{cases}
0,&1\leq j\leq N-1-r,\\
1,&N-r\leq j\leq N-1,
\end{cases} && \text{integrate the one jump in }z_j.
\end{align}
These $N$ vectors are exactly the listed states with $r$ trailing ones.

\noindent\textbf{Final Result.}
\[
\boxed{\frac{E_{\{m_n\}}}{C}=\sum_{j=1}^{N-2}\left[\left(m_j-\frac{j}{N}\right)-\left(m_{j+1}-\frac{j+1}{N}\right)\right]^2+\left(m_1-\frac{1}{N}\right)^2+\left(m_{N-1}-\frac{N-1}{N}\right)^2,\quad E_{\rm gs}=C\frac{N-1}{N}\text{ with minimizers }\{|0,\ldots,0\rangle,\ldots,|1,\ldots,1\rangle\}}
\]
\hfill$\blacksquare$
